<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,fmtDate} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import StatusBadge from '../components/StatusBadge.vue';import PrivateImage from '../components/PrivateImage.vue'
const rows=ref<any[]>([]),search=ref(''),from=ref(''),to=ref(''),next=ref<string|null>(null);const {error,busy,act}=usePage();async function load(url?:string,append=false){const {data}=await api.get(url||`inspections/?search=${encodeURIComponent(search.value)}&from=${from.value}&to=${to.value}`);rows.value=append?[...rows.value,...data.results]:data.results;next.value=data.next}onMounted(()=>act(()=>load()))
</script>
<template><div class="mb-7 flex justify-between gap-4"><div><h1 class="heading">Historial de inspecciones</h1><p class="subheading">Cada imagen, su modelo y sus resultados.</p></div><RouterLink to="/detection" class="btn self-start">Nueva inspección</RouterLink></div><Notice :error="error"/><form @submit.prevent="act(()=>load())" class="mb-5 grid gap-3 md:grid-cols-4"><input v-model="search" class="input" placeholder="Buscar imagen…"/><input v-model="from" type="date" aria-label="Desde" class="input"/><input v-model="to" type="date" aria-label="Hasta" class="input"/><button class="btn-secondary" :disabled="busy">Filtrar / Actualizar</button></form><div v-if="rows.length" class="table-wrap bg-white"><table class="data-table"><thead><tr><th>Imagen</th><th>Estado</th><th>Lesiones</th><th>Tiempo</th><th>Fecha</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><div class="flex items-center gap-3"><PrivateImage :src="`inspections/${row.id}/file/`" class="h-12 w-12 rounded-lg object-contain"/><div><p class="max-w-52 truncate font-medium">{{row.name}}</p><span class="text-[10px] text-slate-400">{{row.model_name}}</span></div></div></td><td><StatusBadge :value="row.job.state"/></td><td>{{row.job.state==='succeeded'?row.detections.length:'—'}}</td><td>{{row.inference_ms!==null?row.inference_ms.toFixed(1)+' ms':'—'}}</td><td class="text-xs text-slate-500">{{fmtDate(row.created_at)}}</td><td><RouterLink :to="'/inspections/'+row.id" class="text-xs font-semibold text-emerald-700">Ver detalle →</RouterLink></td></tr></tbody></table></div><EmptyState v-else title="Sin inspecciones" text="Las imágenes que envíes a detección aparecerán aquí."/><button v-if="next" class="btn-secondary mt-5" @click="act(()=>load(next!,true))">Cargar más</button></template>
